import{_ as e,o as t,c as o,a2 as i}from"./chunks/framework.D8Tso2Ul.js";const p=JSON.parse('{"title":"¿Qué es el DS 44?","description":"","frontmatter":{},"headers":[],"relativePath":"ds44/index.md","filePath":"ds44/index.md"}'),r={name:"ds44/index.md"};function n(s,a,d,l,c,m){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="¿que-es-el-ds-44" tabindex="-1">¿Qué es el DS 44? <a class="header-anchor" href="#¿que-es-el-ds-44" aria-label="Permalink to &quot;¿Qué es el DS 44?&quot;">​</a></h1><p>El <strong>Decreto Supremo N.º 44 (DS 44)</strong> del Ministerio del Trabajo y Previsión Social es la norma chilena que aprueba el <strong>nuevo reglamento sobre gestión preventiva de los riesgos laborales</strong> para la prevención de accidentes del trabajo y enfermedades profesionales. Reemplaza al antiguo DS 40 y moderniza las obligaciones de las empresas en materia de Seguridad y Salud en el Trabajo (SST).</p><p>El DS 44 pone el foco en un <strong>enfoque sistémico y preventivo</strong>: ya no basta con tener documentos archivados, sino que la empresa debe demostrar un ciclo continuo de identificación de peligros, evaluación de riesgos, aplicación de medidas de control y verificación de su cumplimiento.</p><h2 id="¿a-quien-obliga" tabindex="-1">¿A quién obliga? <a class="header-anchor" href="#¿a-quien-obliga" aria-label="Permalink to &quot;¿A quién obliga?&quot;">​</a></h2><p>A toda empresa, faena o establecimiento, con especial exigencia en la industria de la construcción por su nivel de riesgo. Las obligaciones centrales son:</p><ul><li>Mantener un <strong>Sistema de Gestión de SST</strong> documentado y vigente.</li><li>Elaborar y mantener actualizada la <strong>Matriz de Identificación de Peligros y Evaluación de Riesgos (MIPER / MIPPER)</strong> por cada cargo y actividad.</li><li>Entregar y registrar los <strong>Elementos de Protección Personal (EPP)</strong>.</li><li>Realizar <strong>capacitaciones e inducciones</strong> obligatorias (Art. 16) y dejar registro.</li><li><strong>Investigar incidentes y accidentes</strong> con análisis de causa raíz.</li><li>Mantener <strong>registros firmados</strong> y disponibles ante fiscalización.</li></ul><h2 id="¿como-lo-automatiza-build-serve" tabindex="-1">¿Cómo lo automatiza Build &amp; Serve? <a class="header-anchor" href="#¿como-lo-automatiza-build-serve" aria-label="Permalink to &quot;¿Cómo lo automatiza Build &amp; Serve?&quot;">​</a></h2><p>La plataforma traduce cada obligación del DS 44 en un flujo digital con trazabilidad completa. En lugar de carpetas físicas, cada documento, firma y capacitación queda registrado, fechado y disponible para auditoría.</p><table tabindex="0"><thead><tr><th>Obligación DS 44</th><th>Cómo lo resuelve la plataforma</th><th>Módulo</th></tr></thead><tbody><tr><td>Sistema de gestión documentado</td><td>Documentos obligatorios precreados por fase de obra</td><td><a href="/manual/modulos/documentos.html">Documentos</a></td></tr><tr><td>MIPER / MIPPER por cargo</td><td>Generación asistida por IA + firma</td><td><a href="/manual/modulos/asistente-ia.html">Asistente IA</a></td></tr><tr><td>Entrega de EPP registrada</td><td>Acta de entrega con firma de trabajador y supervisor</td><td><a href="/manual/ds44/epp.html">Documentos</a></td></tr><tr><td>Capacitaciones e inducciones</td><td>Registro de asistencia + firma del relator</td><td><a href="/manual/modulos/actividades.html">Actividades</a></td></tr><tr><td>Investigación de incidentes</td><td>Reporte con clasificación y causa raíz</td><td><a href="/manual/modulos/incidentes.html">Incidentes</a></td></tr><tr><td>Registros firmados y trazables</td><td>Firma PIN/presencial inmutable con IP + timestamp</td><td><a href="/manual/modulos/firmas.html">Firmas</a></td></tr><tr><td>Cumplimiento por etapa de obra</td><td>Verificación automática al avanzar de fase</td><td><a href="/manual/modulos/obras.html">Obras</a></td></tr></tbody></table><h2 id="el-ciclo-de-mejora-continua" tabindex="-1">El ciclo de mejora continua <a class="header-anchor" href="#el-ciclo-de-mejora-continua" aria-label="Permalink to &quot;El ciclo de mejora continua&quot;">​</a></h2><p>El DS 44 se apoya en el <strong>ciclo de Deming (PDCA)</strong>: Planificar → Hacer → Verificar → Actuar. Build &amp; Serve modela cada obra según este ciclo normativo, independiente de su etapa física de construcción. Revisa <a href="/manual/ds44/fases-obra.html">Fases de obra</a> para entender cómo se relacionan ambas dimensiones.</p><div class="tip custom-block"><p class="custom-block-title">Siguiente paso</p><p>Revisa el catálogo completo de <a href="/manual/ds44/documentos-obligatorios.html">Documentos obligatorios</a> que la plataforma exige y precrea para cada obra.</p></div>',12)])])}const g=e(r,[["render",n]]);export{p as __pageData,g as default};
